        Self::CircuitOpen => write!(f, \"AgentdCircuitOpen: consecutive failures exceeded configured threshold\"),\n            Self::UnsupportedInput(v) => write!(f, \"AgentdUnsupportedInput: {v}\"),\n        }\n    }\n}\nimpl std::error::Error for BackendError {}\n\npub struct TurnRequest {\n    pub req_id: String,\n    /// Polaris session key; the Pi adapter maps it to the daemon's UUID.\n    pub session_id: String,\n    pub conversation_id: Option<String>,\n    pub prompt: String,\n    pub permission: PermissionMode,\n    pub model: Option<serde_json::Value>,\n    pub cwd: PathBuf,\n    pub attachments: Vec<PathBuf>,\n    pub account_id: Option<String>,\n    pub timeout: Option<Duration>,\n    pub(crate) legacy: Option<(AppHandle, ChatSendArgs)>,\n}\n#[derive(Debug, Clone, Serialize)]\n#[serde(rename_all = \"camelCase\")]\npub struct BackendStatus {\n    pub backend: String,\n    pub agentd_version: Option<String>,\n    pub pid: Option<u32>,\n    pub restarts: u32,\n    pub circuit_open: bool,\n    pub healthy: bool,\n    pub last_error: Option<String>,\n}\nimpl BackendStatus {\n    pub(crate) fn new(name: &str) -> Self {\n        Self { backend: name.into(), agentd_version: None, pid: None, restarts: 0,\n            circuit_open: false, healthy: false, last_error: None }\n    }\n}\npub trait AgentBackend: Send + Sync {\n    fn start(&self, input: TurnRequest) -> anyhow::Result<EventStream>;\n    fn cancel(&self, req_id: &str) -> anyhow::Result<()>;\n    fn close(&self, session_id: &str) -> anyhow::Result<()>;\n    fn models(&self) -> anyhow::Result<serde_json::Value>;\n    fn status(&self) -> BackendStatus;\n    fn is_running(&self, req_id: &str) -> bool;\n    fn shutdown(&self);\n}\nstatic SELECTED: once_cell::sync::OnceCell<Arc<dyn AgentBackend>> = once_cell::sync::OnceCell::new();\npub fn selected() -> anyhow::Result<Arc<dyn AgentBackend>> {\n    SELECTED.get_or_try_init(|| {\n        let config = config::Config::load()?;\n        let backend: Arc<dyn AgentBackend> = match config::BackendKind::parse(&config.agent.backend)? {\n            config::BackendKind::Pi => Arc::new(pi::PiBackend::new(config.agentd)?),\n            config::BackendKind::ClaudeCli => Arc::new(claude_cli::ClaudeCliBackend),\n        };\n        Ok(backend)\n    }).cloned()\n}\n#[cfg_attr(feature = \"desktop\", tauri::command)]\npub fn agent_backend_status() -> Result<BackendStatus, String> {\n    selected().map(|b| b.status()).map_err(|e| e.to_string())\n}\npub fn close_session(id: &str) {\n    if let Some(b) = SELECTED.get() { let _ = b.close(id); }\n    else { claude_cli::pool::kill_conv(id); }\n}\npub fn shutdown() {\n    if let Some(b) = SELECTED.get() { b.shutdown(); }\n    claude_cli::pool::kill_all();\n}\npub fn collect<F: FnMut(&str, &str)>(\n    backend: &dyn AgentBackend, input: TurnRequest, mut on_event: F,\n) -> anyhow::Result<String> {\n    let req = input.req_id.clone();\n    let polling = Duration::from_millis(config::Config::load()?.agentd.request_timeout_ms);\n    let deadline = input.timeout.map(|timeout| std::time::Instant::now() + timeout);\n    let stream = backend.start(input)?;\n    let mut result = String::new();\n    let mut error = None;\n    loop {\n        let event = match stream.recv_timeout(deadline.map(|d| d.saturating_duration_since(std::time::Instant::now()).min(polling)).unwrap_or(polling)) {\n            Ok(e) => e,\n            Err(e) if matches!(e.downcast_ref(), Some(stream::StreamError::Timeout))\n                && deadline.is_none_or(|d| std::time::Instant::now() < d) => continue,\n            Err(e) => { let _ = backend.cancel(&req); return Err(e); }\n        };\n        match event.kind.as_str() {\n            \"delta\" => { let text = event.text.as_deref().unwrap_or_default(); result.push_str(text); on_event(\"delta\", text); }\n            \"tool\" => on_event(\"tool\", event.tool.as_deref().unwrap_or_default()),\n            \"error\" => error = event.text,\n            \"done\" => return match error { Some(e) => Err(anyhow::anyhow!(e)), None => Ok(result) },\n            _ => {}\n        }\n    }\n}\npub(crate) fn event(req: &str, conv: Option<&str>, kind: &str, text: Option<String>) -> crate::chat::ChatStreamEvent {\n    crate::chat::ChatStreamEvent { req_id: req.into(), conversation_id: conv.map(str::to_owned), kind: kind.into(), text, tool: None }\n}\n//! UI delivery reuses the existing prompt assembly, artifact diff and persistence.\nuse super::*;\nuse crate::chat::ChatStreamEvent;\n#[cfg(feature = \"desktop\")]\nuse tauri::Emitter;\n\npub(crate) fn run_chat(app: &AppHandle, req: &str, args: ChatSendArgs) -> Result<(), String> {\n    let backend = selected().map_err(|e| e.to_string())?;\n    let legacy = backend.status().backend == \"claude-cli\";\n    let conv = args.conversation_id.clone();\n    let permission = match args.permission_mode {\n        PermissionMode::Manual => PermissionMode::Manual, PermissionMode::AutoAll => PermissionMode::AutoAll,\n        PermissionMode::AutoCurrent => PermissionMode::AutoCurrent, PermissionMode::Deny => PermissionMode::Deny,\n    };\n    let mut input = TurnRequest {\n        req_id: req.into(), session_id: conv.clone().unwrap_or_else(|| req.into()),\n        conversation_id: conv.clone(), prompt: args.prompt.clone(), permission,\n        model: None, cwd: claude_cli::pipeline::effective_cwd(None), attachments: vec![],\n        account_id: None, timeout: None, legacy: None,\n    };\n    let mut snapshot = None;\n    let mut notice = None;\n    if legacy { input.legacy = Some((app.clone(), args)); }\n    else {\n        if args.use_sandbox { return Err(BackendError::UnsupportedInput(\"sandbox requires P3 tool routing\").to_string()); }\n        if args.provider_id.as_deref().is_some_and(|p| !p.is_empty() && p != \"auto\") {\n            return Err(BackendError::UnsupportedInput(\"provider selection requires P4 mapping\").to_string());\n        }\n        let prepared = claude_cli::pipeline::prepare(args);\n        input.prompt = prepared.plan.full_text();\n        input.cwd = claude_cli::pipeline::effective_cwd(prepared.project_work_dir.as_deref().map(std::path::Path::new));\n        notice = prepared.image_notice;\n        snapshot = Some((prepared.art_dir, prepared.art_before));\n    }\n    if crate::runtime::procs::CHILDREN.take_cancel(req) {\n        emit(app, event(req, conv.as_deref(), \"done\", None));\n        return Ok(());\n    }\n    let stream = backend.start(input).map_err(|e| e.to_string())?;\n    let mut finalizer = None;\n    let timeout = Duration::from_millis(config::Config::load().map_err(|e| e.to_string())?.agentd.request_timeout_ms);\n    loop {\n        let ev = match stream.recv_timeout(timeout) {\n            Ok(event) => event,\n            // Only the supervisor sees all agentd events (including hidden reasoning/usage).\n            // Let it own turn deadlines and deliver the specific error followed by done.\n            Err(error) if matches!(error.downcast_ref(), Some(stream::StreamError::Timeout)) => continue,\n            Err(error) => { let _ = backend.cancel(req); return Err(error.to_string()); }\n        };\n        if ev.kind == \"done\" {\n            if let (Some(finalizer), Some((artifacts, before))) = (finalizer.take(), snapshot.take()) {\n                let finalizer: claude_cli::pipeline::TurnStream = finalizer;\n                finalizer.finish(&artifacts, &before);\n            } else { emit(app, ev); }\n            if conv.is_none() { let _ = backend.close(req); }\n            crate::runtime::procs::CHILDREN.take_cancel(req);\n            break;\n        }\n        if ev.kind == \"meta\" && !legacy {\n            emit(app, ev);\n            finalizer = Some(claude_cli::pipeline::TurnStream::new(app.clone(), req.into(), conv.clone(), notice.take()));\n            continue;\n        }\n        if let Some(finalizer) = &mut finalizer { finalizer.record_backend_event(&ev); }\n        emit(app, ev);\n    }\n    Ok(())\n}\npub(crate) fn emit(app: &AppHandle, event: ChatStreamEvent) { let _ = app.emit(\"chat:stream\", event); }\nimport { mkdtempSync, rmSync } from \"node:fs\";\nimport { tmpdir } from \"node:os\";\nimport { join } from \"node:path\";\nimport { setTimeout as delay } from \"node:timers/promises\";\nimport { registerFauxProvider } from \"@earendil-works/pi-ai/compat\";\nimport type { ExtensionFactory } from \"@earendil-works/pi-coding-agent\";\nimport { loadConfig, mergeConfig } from \"../src/config/load.ts\";\nimport type { ConfigPatch } from \"../src/config/schema.ts\";\nimport { Daemon } from \"../src/daemon.ts\";\nimport type { ProtocolEvent } from \"../src/protocol/events.ts\";\nimport type { Response } from \"../src/protocol/schema.ts\";\n\nexport type Steps = Parameters<ReturnType<typeof registerFauxProvider>[\"setResponses\"]>[0];\nexport function providerConfig(model: ReturnType<ReturnType<typeof registerFauxProvider>[\"getModel\"]>) {\n  if (!model) throw new Error(\"Missing faux model\");\n  const { id, name, api, baseUrl, reasoning, input, cost, contextWindow, maxTokens } = model;\n  return { id: model.provider, api, baseUrl,\n    models: [{ id, name, reasoning, input, cost, contextWindow, maxTokens }] };\n}\nexport async function harness(steps: Steps = [], patch: ConfigPatch = {}, factories: ExtensionFactory[] = []) {\n  const dir = mkdtempSync(join(tmpdir(), \"polaris-agentd-\"));\n  const faux = registerFauxProvider({ models: [{ id: \"test\", reasoning: true }], tokensPerSecond: Infinity });\n  faux.setResponses(steps);\n  const model = faux.getModel();\n  const config = mergeConfig(loadConfig(), {\n    sessionDir: join(dir, \"sessions\"), defaultModel: { provider: model.provider, id: model.id },\n    providers: [providerConfig(model)], tools: [], ...patch,\n  });\n  const events: ProtocolEvent[] = [];\n  const logs: string[] = [];\n  const daemon = await Daemon.create(config, (value) => {\n    if (value.type === \"event\") events.push(value);\n  }, (line) => logs.push(line), { factories });\n  await daemon.models.apply(config, { [model.provider]: \"test-secret-key-7654321\" });\n  let nextId = 0;\n  const request = (method: string, params: object = {}) => daemon.handle({ id: ++nextId, method, params });\n  return { dir, faux, daemon, events, logs, request,\n    async close() {\n      await daemon.shutdown();\n      faux.unregister();\n      rmSync(dir, { recursive: true, force: true });\n    },\n  };\n}\nexport function result<T>(response: Response): T {\n  if (!response.ok) throw new Error(JSON.stringify(response));\n  return response.result as T;\n}\nexport async function until(predicate: () => boolean): Promise<void> {\n  const end = Date.now() + 5000;\n  while (!predicate()) {\n    if (Date.now() > end) throw new Error(\"Timed out waiting for condition\");\n    await delay(5);\n  }\n}\nimport assert from \"node:assert/strict\";\nimport { readdirSync, readFileSync } from \"node:fs\";\nimport { join } from \"node:path\";\nimport { test } from \"node:test\";\nimport { setTimeout as delay } from \"node:timers/promises\";\nimport { fauxAssistantMessage } from \"@earendil-works/pi-ai\";\nimport { harness, result, until, type Steps } from \"./helpers.ts\";\n\nconst slow: Steps[number] = (_context, options) => new Promise((resolve) => {\n  const timer = setTimeout(() => resolve(fauxAssistantMessage(\"late\")), 2000);\n  options?.signal?.addEventListener(\"abort\", () => {\n    clearTimeout(timer);\n    resolve(fauxAssistantMessage(\"\", { stopReason: \"aborted\" }));\n  }, { once: true });\n});\nasync function open(h: Awaited<ReturnType<typeof harness>>) {\n  return result<{ sessionId: string }>(await h.request(\"session.open\", { cwd: h.dir })).sessionId;\n}\ntest(\"open → prompt → close → fresh daemon resumes history by id\", async () => {\n  const h = await harness([fauxAssistantMessage(\"remember me\")]);\n  try {\n    const id = await open(h);\n    const turn = result<{ turnId: string }>(await h.request(\"prompt\", { sessionId: id, tex