\n\n    /// 一份 npm 安装的两个入口 **不得**被报成冲突 —— 这是最容易误报、也最吓人的一条。\n    #[test]\n    fn single_npm_install_reports_no_conflict() {\n        let all = vec![\n            PathBuf::from(r\"D:\\npm\\claude.cmd\"),\n            PathBuf::from(r\"D:\\npm\\node_modules\\@anthropic-ai\\claude-code\\bin\\claude.exe\"),\n        ];\n        let v = |_: &Path| Some(\"2.1.220\".to_string());\n        let out = install_conflicts(&all, Some(&all[1]), Some(&all[0]), &v);\n        assert!(out.is_empty(), \"同一份安装不该报冲突, 实得: {out:?}\");\n    }\n\n    /// npm 一份 + 原生脚本一份, 版本还不同 —— 必须同时报「多份并存」与「版本不一致」,\n    /// 且两条都是 high (这正是「更新完版本号纹丝不动」的根因)。\n    #[test]\n    fn two_installs_with_different_versions_report_both_conflicts() {\n        let npm = PathBuf::from(r\"D:\\npm\\claude.cmd\");\n        let native = PathBuf::from(r\"C:\\Users\\x\\.local\\bin\\claude.exe\");\n        let all = vec![npm.clone(), native.clone()];\n        let v = |p: &Path| {\n            Some(if p == npm.as_path() { \"2.0.1\" } else { \"2.1.220\" }.to_string())\n        };\n        let out = install_conflicts(&all, Some(&native), Some(&npm), &v);\n        let keys: Vec<&str> = out.iter().map(|c| c.key.as_str()).collect();\n        assert!(keys.contains(&\"claude-multi\"), \"应报多份并存: {keys:?}\");\n        assert!(\n            keys.contains(&\"claude-version-mismatch\"),\n            \"版本不同应额外报版本冲突: {keys:?}\"\n        );\n        // 应用解析到 native、终端首个命中 npm → 还要报「两边跑的不是同一份」\n        assert!(\n            keys.contains(&\"claude-app-vs-terminal\"),\n            \"应用与终端解析到不同安装时必须报出来: {keys:?}\"\n        );\n        assert!(out.iter().all(|c| c.severity == \"high\"));\n        // 报告里要能看到两份各自的版本, 否则用户不知道该删哪个\n        let multi = out.iter().find(|c| c.key == \"claude-multi\").unwrap();\n        assert!(multi.paths.iter().any(|l| l.contains(\"2.0.1\")));\n        assert!(multi.paths.iter().any(|l| l.contains(\"2.1.220\")));\n    }\n\n    /// Store 执行别名 (WindowsApps 下的 0 字节占位) 必须被认出来并单独报, 且**不能**被\n    /// 当成一份真安装并进「多份并存」—— 否则干净机器会平白多出一条 high 冲突。\n    #[test]\n    #[cfg(windows)]\n    fn store_alias_is_flagged_but_not_counted_as_install() {\n        let dir = std::env::temp_dir()\n            .join(\"polaris-verify-test\")\n            .join(\"WindowsApps\");\n        std::fs::create_dir_all(&dir).expect(\"建测试目录\");\n        let alias = dir.join(\"claude.exe\");\n        std::fs::write(&alias, b\"\").expect(\"造 0 字节占位符\"); // 真身别名就是 0 字节重解析点\n        let real = PathBuf::from(r\"C:\\Users\\x\\.local\\bin\\claude.exe\");\n\n        let out = install_conflicts(\n            &[alias.clone(), real.clone()],\n            Some(&real),\n            Some(&real),\n            &|_| Some(\"2.1.220\".into()),\n        );\n        let keys: Vec<&str> = out.iter().map(|c| c.key.as_str()).collect();\n        assert!(keys.contains(&\"claude-store-alias\"), \"应认出别名: {keys:?}\");\n        assert!(\n            !keys.contains(&\"claude-multi\"),\n            \"别名不是一份安装, 不该凑成「多份并存」: {keys:?}\"\n        );\n        let _ = std::fs::remove_file(&alias);\n    }\n\n    /// 冲突按严重度排序 —— 面板从上往下看, high 必须在最前面。\n    #[test]\n    fn conflicts_sorted_high_first() {\n        let mut v = vec![\n            conflict(\"a\", \"low\", \"t\", \"d\".into(), vec![], false),\n            conflict(\"b\", \"high\", \"t\", \"d\".into(), vec![], false),\n            conflict(\"c\", \"medium\", \"t\", \"d\".into(), vec![], false),\n        ];\n        let rank = |s: &str| match s {\n            \"high\" => 0,\n            \"medium\" => 1,\n            _ => 2,\n        };\n        v.sort_by_key(|c| rank(&c.severity));\n        assert_eq!(\n            v.iter().map(|c| c.key.as_str()).collect::<Vec<_>>(),\n            vec![\"b\", \"c\", \"a\"]\n        );\n    }\n\n    /// 冒烟必须**只读**: 它跑在用户真机上, 参数里绝不能出现放开写权限的工具集。\n    /// (防回归 —— 有人图省事把 allowedTools 改成全放开, 冒烟就会真去改用户的文件。)\n    #[test]\n    fn smoke_args_are_read_only() {\n        let tools_idx = SMOKE_ARGS\n            .iter()\n            .position(|a| *a == \"--allowedTools\")\n            .expect(\"冒烟必须显式限定工具集\");\n        assert_eq!(SMOKE_ARGS[tools_idx + 1], \"Read\", \"冒烟只放行 Read\");\n        for bad in [\"Write\", \"Edit\", \"Bash\", \"acceptEdits\"] {\n            assert!(\n                !SMOKE_ARGS.iter().any(|a| a.contains(bad)),\n                \"冒烟参数不得含 {bad}\"\n            );\n        }\n    }\n\n    /// 整条链路不 panic, 且字段自洽 (本机装没装 claude 都要能跑完)。\n    #[test]\n    fn verify_sync_is_self_consistent() {\n        let r = env_verify_sync(false);\n        assert!(!r.deep);\n        assert!(!r.steps.is_empty());\n        assert!(\n            r.steps.iter().all(|s| matches!(\n                s.status.as_str(),\n                \"ok\" | \"fail\" | \"warn\" | \"skip\"\n            )),\n            \"step.status 只能是这四种\"\n        );\n        assert!(\n            r.conflicts\n                .iter()\n                .all(|c| matches!(c.severity.as_str(), \"high\" | \"medium\" | \"low\")),\n            \"conflict.severity 只能是这三种\"\n        );\n        // 没装 claude 时 ok 必须为 false —— 不能把「查不到」报成健康\n        if !r.app_runnable {\n            assert!(!r.ok);\n        }\n        assert!(!r.summary.is_empty());\n    }\n}\n// Pins the slice of the Pi SDK that agentd depends on. If a Pi upgrade breaks\n// any of these behaviours, this file fails before agentd code does.\nimport assert from \"node:assert/strict\";\nimport { mkdtempSync, rmSync } from \"node:fs\";\nimport { tmpdir } from \"node:os\";\nimport { join } from \"node:path\";\nimport { test } from \"node:test\";\n\nimport { fauxAssistantMessage, fauxToolCall, InMemoryCredentialStore } from \"@earendil-works/pi-ai\";\nimport { registerFauxProvider } from \"@earendil-works/pi-ai/compat\";\nimport {\n\ttype AgentSessionEvent,\n\tcreateAgentSession,\n\tdefineTool,\n\tModelRuntime,\n\tSessionManager,\n\tSettingsManager,\n} from \"@earendil-works/pi-coding-agent\";\nimport { Type } from \"typebox\";\n\nconst FAUX_KEY = \"faux-key\";\nconst TOOL_NAME = \"polaris_echo\";\n\nasync function fauxSession(responses: Parameters<ReturnType<typeof registerFauxProvider>[\"setResponses\"]>[0]) {\n\tconst dir = mkdtempSync(join(tmpdir(), \"agentd-contract-\"));\n\tconst faux = registerFauxProvider();\n\tfaux.setResponses(responses);\n\tconst model = faux.getModel();\n\tconst credentials = new InMemoryCredentialStore();\n\tawait credentials.modify(model.provider, async () => ({ type: \"api_key\", key: FAUX_KEY }));\n\tconst modelRuntime = await ModelRuntime.create({ credentials, modelsPath: null, allowModelNetwork: false });\n\tconst { id, name, api, reasoning, input, cost, contextWindow, maxTokens, baseUrl } = model;\n\tconst models = [{ id, name, api, reasoning, input, cost, contextWindow, maxTokens, baseUrl }];\n\tmodelRuntime.registerProvider(model.provider, { baseUrl, api, models });\n\tconst toolCalls: unknown[] = [];\n\tconst echo = defineTool({\n\t\tname: TOOL_NAME,\n\t\tlabel: \"Echo\",\n\t\tdescription: \"Echo the given text back.\",\n\t\tparameters: Type.Object({ text: Type.String() }),\n\t\texecute: async (_id, params) => {\n\t\t\ttoolCalls.push(params);\n\t\t\treturn { content: [{ type: \"text\", text: `echo:${params.text}` }], details: {} };\n\t\t},\n\t});\n\tconst { session } = await createAgentSession({\n\t\tcwd: dir,\n\t\tagentDir: dir,\n\t\tmodel,\n\t\tmodelRuntime,\n\t\t// `tools` is an allowlist over *all* tools: `tools: []` silently disables custom\n\t\t// tools too. `noTools: \"builtin\"` drops only read/bash/edit/write.\n\t\tnoTools: \"builtin\",\n\t\tcustomTools: [echo],\n\t\tsessionManager: SessionManager.inMemory(dir),\n\t\tsettingsManager: SettingsManager.inMemory({ compaction: { enabled: false } }),\n\t});\n\tconst events: AgentSessionEvent[] = [];\n\tsession.subscribe((event) => events.push(event));\n\tconst close = () => {\n\t\tsession.dispose();\n\t\tfaux.unregister();\n\t\trmSync(dir, { recursive: true, force: true });\n\t};\n\treturn { session, events, toolCalls, close };\n}\n\ntest(\"prompt runs a custom tool and streams the final answer\", async () => {\n\tconst { session, events, toolCalls, close } = await fauxSession([\n\t\tfauxAssistantMessage(fauxToolCall(TOOL_NAME, { text: \"hi\" }), { stopReason: \"toolUse\" }),\n\t\tfauxAssistantMessage(\"done\"),\n\t]);\n\ttry {\n\t\tawait session.prompt(\"use the tool\");\n\t\tassert.deepEqual(toolCalls, [{ text: \"hi\" }]);\n\t\tassert.equal(session.getLastAssistantText(), \"done\");\n\t\tconst types = new Set(events.map((event) => event.type));\n\t\tfor (const expected of [\"agent_start\", \"tool_execution_start\", \"tool_execution_end\", \"message_end\", \"agent_end\"]) {\n\t\t\tassert.ok(types.has(expected as AgentSessionEvent[\"type\"]), `missing event ${expected}`);\n\t\t}\n\t} finally {\n\t\tclose();\n\t}\n});\n\ntest(\"abort stops a running turn and leaves the session usable\", async () => {\n\tconst { session, close } = await fauxSession([\n\t\t() => new Promise((resolve) => setTimeout(() => resolve(fauxAssistantMessage(\"late\")), 5_000)),\n\t\tfauxAssistantMessage(\"after abort\"),\n\t]);\n\ttry {\n\t\tconst running = session.prompt(\"slow\").catch(() => undefined);\n\t\tawait new Promise((resolve) => setTimeout(resolve, 50));\n\t\tawait session.abort();\n\t\tawait running;\n\t\tawait session.prompt(\"again\");\n\t\tassert.equal(session.getLastAssistantText(), \"after abort\");\n\t} finally {\n\t\tclose();\n\t}\n});\n","exit_code":0,"status":"completed"}}
