input)?;\n    let mut result = String::new();\n    let mut error = None;\n    loop {\n        let event = match stream.recv_timeout(deadline.map(|d| d.saturating_duration_since(std::time::Instant::now()).min(polling)).unwrap_or(polling)) {\n/** 路由调试一行：每个候选专家的命中明细 */\r\nexport interface ExpertDebugRow {\r\n  id: string;\r\n  name: string;\r\n  group: string;\r\n  hitSignals: string[];\r\n  similarity: number;\r\n  wouldSelect: boolean;\r\n}\r\n\r\n/** 按知识库反推的专家团推荐 */\r\nexport interface KbRecommendation {\r\n  team: ExpertTeam | null;\r\n  reason: string;\r\n  topExperts: ExpertCard[];\r\n  matchedTopics: string[];\r\n  corpusSize: number;\r\n}\r\n\r\nexport const expert = {\r\n  list: () => invoke<ExpertCard[]>(\"expert_list\"),\r\n  listByGroup: (group: string) => invoke<ExpertCard[]>(\"expert_list_by_group\", { group }),\r\n  groups: () => invoke<ExpertGroup[]>(\"expert_groups\"),\r\n  route: (req: RouteRequest) => invoke<ExpertMatch[]>(\"expert_route\", { req }),\r\n  get: (id: string) => invoke<ExpertCard | null>(\"expert_get\", { id }),\r\n  matchAuto: (query: string) => invoke<ExpertMatch[]>(\"expert_match_auto\", { query }),\r\n  /** 把专家的 CLAUDE.md 模板应用到项目（写 CLAUDE.md + 记录 persona_id）；已有内容需 overwrite=true */\r\n  apply: (projectId: string, expertId: string, overwrite = false) =>\r\n    invoke<void>(\"expert_apply\", { projectId, expertId, overwrite }),\r\n  /** 取专家/专家团头像 base64 data URL（失败返回 null，前端落 gradient 占位） */\r\n  getAvatar: (id: string) => invoke<string | null>(\"expert_avatar\", { id }),\r\n  /** 一次性取全部 9 张头像（按槽位），配合 avatarSlot(id) 本地映射，避免逐卡 IPC 卡顿 */\r\n  avatarSlots: () => invoke<string[]>(\"expert_avatar_slots\"),\r\n  /** 召集专家团：分析任务并返回推荐的专家列表（最多5个） */\r\n  teamSpawn: (projectId: string, task: string) =>\r\n    invoke<ExpertMatch[]>(\"expert_team_spawn\", { projectId, taskDescription: task }),\r\n  /** 查询项目当前专家团各专家的状态（idle|working|done） */\r\n  agentsStatus: (projectId: string) =>\r\n    invoke<ExpertAgentStatus[]>(\"expert_agents_status\", { projectId }),\r\n  /** 全部业务专家团 */\r\n  teams: () => invoke<ExpertTeam[]>(\"expert_teams\"),\r\n  /** 取单个业务团 */\r\n  teamGet: (id: string) => invoke<ExpertTeam | null>(\"expert_team_get\", { id }),\r\n  /** 把业务团应用到项目（组装战略师领衔的编排型 CLAUDE.md）；已有内容需 overwrite=true */\r\n  teamApply: (projectId: string, teamId: string, overwrite = false) =>\r\n    invoke<void>(\"team_apply\", { projectId, teamId, overwrite }),\r\n  /** 「下载」专家：返回其完整 CLAUDE.md 文本 */\r\n  exportExpert: (id: string) => invoke<string>(\"expert_export\", { id }),\r\n  /** 「下载」业务团：返回其完整编排型 CLAUDE.md 文本 */\r\n  exportTeam: (id: string) => invoke<string>(\"team_export\", { id }),\r\n  /** 调试某条查询的智能匹配，返回全部命中专家的打分明细 */\r\n  routeDebug: (query: string) => invoke<ExpertDebugRow[]>(\"expert_route_debug\", { query }),\r\n  /** 按知识库反推该配哪支专家团（scope 可限定子目录，空=全库） */\r\n  recommendFromKb: (scope?: string) =>\r\n    invoke<KbRecommendation>(\"expert_recommend_from_kb\", { scope: scope ?? null }),\r\n};\r\n//! 专家 CLAUDE.md 文档 — 每个专家一份可编辑的 .md 提示词（放仓库源码、编译期内嵌）。\n//!\n//! 取数顺序:\n//!   1. `src/templates/experts/<group>/<id>.md` —— 该专家**亲自写好的**提示词(强烈推荐,\n//!      调它就是调这个文件,改完重编即生效)。文件内可用下方变量占位,也可全篇手写散文。\n//!   2. 找不到该文件 → 回落 `GENERIC.md` 通用骨架 + 变量替换(保证任何专家都有内容)。\n//!\n//! 变量: {{NAME}} · {{ID}} · {{GROUP}} · {{ROLE}} · {{DESCRIPTION}} · {{KEYWORDS}} ·\n//!       {{CAPABILITIES}} · {{TRIGGER_SIGNALS}} · {{COMPLEMENTS}} ·\n//!       {{EXCLUSIVE_WITH}} · {{COST_TIER}} · {{TIMESTAMP}}\n\nuse include_dir::{include_dir, Dir};\nuse std::time::{SystemTime, UNIX_EPOCH};\n\n/// 整个专家提示词目录编进二进制 —— 每加一个 `<group>/<id>.md` 文件,重编后自动可用。\nstatic EXPERTS_DIR: Dir<'_> = include_dir!(\"$CARGO_MANIFEST_DIR/src/templates/experts\");\n\n/// 取某专家的完整提示词正文(供 expert_apply / expert_export / route_block 注入)。\n///\n/// 先找该专家专属 .md(`experts/<group>/<id>.md`),没有再用 GENERIC 骨架。两条路都会做\n/// 变量替换,所以专属文件既能全篇手写、也能内嵌 {{NAME}} 等占位由元数据补全。\npub fn build_expert_doc(\n    ref_path: &str,\n    name: &str,\n    role: &str,\n    description: &str,\n    keywords: &[String],\n    capabilities: &[String],\n    trigger_signals: &[String],\n    complements: &str,\n    exclusive_with: &[String],\n    cost_tier: u8,\n) -> Option<String> {\n    // ref_path 形如 \"experts/marketing/visual-designer.md\";嵌入目录的根就是 experts/,\n    // 所以去掉前缀后用 \"marketing/visual-designer.md\" 查。\n    let rel = ref_path.trim_start_matches(\"experts/\");\n    let parts: Vec<&str> = rel.trim_end_matches(\".md\").split('/').collect();\n    let id = parts.last().unwrap_or(&\"unknown\").to_string();\n    let group = parts\n        .get(parts.len().saturating_sub(2))\n        .unwrap_or(&\"unknown\")\n        .to_string();\n\n    // ① 专家专属提示词文件优先;② 否则通用骨架。\n    let template: String = EXPERTS_DIR\n        .get_file(rel)\n        .and_then(|f| f.contents_utf8())\n        .map(|s| s.to_string())\n        .unwrap_or_else(|| GENERIC_TEMPLATE.to_string());\n\n    let timestamp = current_date();\n    let mut result = template;\n    result = result.replace(\"{{NAME}}\", name);\n    result = result.replace(\"{{ID}}\", &id);\n    result = result.replace(\"{{GROUP}}\", &group);\n    result = result.replace(\"{{ROLE}}\", role);\n    result = result.replace(\"{{DESCRIPTION}}\", description);\n    result = result.replace(\"{{KEYWORDS}}\", &keywords.join(\"、\"));\n    result = result.replace(\n        \"{{CAPABILITIES}}\",\n        &capabilities\n            .iter()\n            .map(|s| format!(\"- **{}**\", s))\n            .collect::<Vec<_>>()\n            .join(\"\\n\"),\n    );\n    result = result.replace(\n        \"{{TRIGGER_SIGNALS}}\",\n        &trigger_signals\n            .iter()\n            .map(|s| format!(\"- **{}**\", s))\n            .collect::<Vec<_>>()\n            .join(\"\\n\"),\n    );\n    result = result.replace(\"{{COMPLEMENTS}}\", complements);\n    result = result.replace(\n        \"{{EXCLUSIVE_WITH}}\",\n        &exclusive_with\n            .iter()\n            .map(|s| s.as_str())\n            .collect::<Vec<_>>()\n            .join(\"、\"),\n    );\n    result = result.replace(\"{{COST_TIER}}\", &cost_tier.to_string());\n    result = result.replace(\"{{TIMESTAMP}}\", &timestamp);\n    Some(result)\n}\n\nfn current_date() -> String {\n    SystemTime::now()\n        .duration_since(UNIX_EPOCH)\n        .ok()\n        .and_then(|d| chrono::DateTime::from_timestamp(d.as_secs() as i64, 0))\n        .map(|dt| dt.format(\"%Y-%m-%d\").to_string())\n        .unwrap_or_else(|| String::new())\n}\n\n/// GENERIC.md 通用骨架（编译期内嵌）—— 仅当某专家还没有专属 .md 时回落使用。\nconst GENERIC_TEMPLATE: &str = include_str!(\"../templates/experts/GENERIC.md\");\n//! Host settings: POLARIS_AGENT_CONFIG JSON, with explicit environment overrides.\nuse serde::{Deserialize, Serialize};\nuse std::path::PathBuf;\nuse super::BackendError;\n\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\npub enum BackendKind { Pi, ClaudeCli }\nimpl BackendKind {\n    pub fn parse(value: &str) -> Result<Self, BackendError> {\n        match value {\n            \"pi\" => Ok(Self::Pi),\n            \"claude-cli\" => Ok(Self::ClaudeCli),\n            other => Err(BackendError::InvalidBackend(other.into())),\n        }\n    }\n}\n#[derive(Debug, Clone, Deserialize)]\n#[serde(default, deny_unknown_fields)]\npub struct Config {\n    pub agent: Agent,\n    pub agentd: Agentd,\n}\nimpl Default for Config {\n    fn default() -> Self { Self { agent: Agent::default(), agentd: Agentd::default() } }\n}\n#[derive(Debug, Clone, Deserialize)]\n#[serde(default, deny_unknown_fields)]\npub struct Agent { pub backend: String }\nimpl Default for Agent { fn default() -> Self { Self { backend: \"pi\".into() } } }\n#[derive(Debug, Clone, Deserialize, Serialize)]\n#[serde(default, rename_all = \"camelCase\", deny_unknown_fields)]\npub struct Agentd {\n    pub node: PathBuf,\n    pub entry: PathBuf,\n    pub node_args: Vec<String>,\n    pub args: Vec<String>,\n    pub isolation: String,\n    pub max_processes: usize,\n    pub idle_ms: u64,\n    pub request_timeout_ms: u64,\n    /// Lost-daemon fallback: 240000 > agentd's 180000 so agentd can finish first.\n    pub turn_idle_timeout_ms: u64,\n    /// Hard turn limit in milliseconds; zero disables it.\n    pub turn_max_ms: u64,\n    #[serde(rename = \"turnTimeoutMs\", deserialize_with = \"reject_turn_timeout\", skip_serializing)]\n    _legacy_turn_timeout: (),\n    pub abort_timeout_ms: u64,\n    pub ping_interval_ms: u64,\n    pub restart_base_ms: u64,\n    pub restart_max_ms: u64,\n    pub restart_jitter_ms: u64,\n    pub failure_threshold: u32,\n    pub stable_reset_ms: u64,\n    pub channel_capacity: usize,\n    pub max_line_bytes: usize,\n    pub delta_batch_ms: u64,\n    pub write_tools: Vec<String>,\n    pub readonly_tools: Vec<String>,\n    /// Existing container managed by polaris-sandbox (or the server operator).\n    pub sandbox_container: String,\n      matrix:\n        os: [ubuntu-latest, windows-latest, macos-latest]\n    runs-on: ${{ matrix.os }}\n    defaults:\n      run:\n        working-directory: src-tauri\n    steps:\n      - uses: actions/checkout@v4\n      - uses: dtolnay/rust-toolchain@stable\n      - uses: Swatinem/rust-cache@v2\n        with:\n          workspaces: src-tauri\n      # macOS: audiopus_sys 从源码静态编 libopus 需要 autotools(autoreconf),\n      # runner 默认没有 → `autogen.sh: autoreconf: command not found`(与 release.yml 同因同修)。\n      - name: Install macOS build deps (autotools for audiopus/libopus)\n        if: matrix.os == 'macos-latest'\n        run: brew install autoconf automake libtool\n      # 引擎编译(server feature) + forge 单测(png/pptx 结构/数页/hex 解码) —— 跨平台一致性守门\n      - name: Forge engine build + tests\n        run: cargo test --no-default-features --features server --lib forge\n      # polaris-cli(polaris-forge 命令行)编译守护: 它拉主 lib 的 server feature,\n      # 与本 job 同侧, 增量编译近零成本。不能进 rust job 的 --workspace(feature 统一会炸)。\n      - name: polaris-cli build check\n        run: cargo check -p polaris-cli\n\n  # macOS「真能出片」运行时验证:装真 Chrome,在 macOS runner 上跑 deck→截图→pptx 全流水线\n  # (无需 Mac 硬件)。证明 macOS 不止编译过,而是真能产出成品。\n  forge-e2e-macos:\n    name: Forge e2e (macOS · 真 Chrome 出 pptx)\n    runs-on: macos-latest\n    defaults:\n      run:\n        working-directory: src-tauri\n    steps:\n      - uses: actions/checkout@v4\n      - uses: dtolnay/rust-toolchain@stable\n      - uses: Swatinem/rust-cache@v2\n        with:\n          workspaces: src-tauri\n      # 同 forge-matrix: macOS 编 audiopus/libopus 需要 autotools。\n      - name: Install macOS build deps (autotools for audiopus/libopus)\n        run: brew install autoconf automake libtool\n      - name: Install Google Chrome\n        run: brew install --cask google-chrome || true\n      - name: 真实 deck→pptx + 文本提取 on macOS\n        # when_chromium_present 同时匹配 deck_to_pptx_e2e 与 extract_text_rects 两个真 Chrome e2e。\n        run: cargo test --no-default-features --features server --lib when_chromium_present -- --nocapture\n\n  frontend:\n    name: Frontend (type-check + build)\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 20\n          cache: npm\n      - run: npm ci\n      # npm run build = vue-tsc --noEmit && vite build (类型检查 + 打包)\n      - run: npm run build\n","exit_code":0,"status":"completed"}}
