rgs);\n        input.model = claude_cli::pipeline::model_for_mode(prepared.work_full).map(serde_json::Value::String);\n        input.prompt = prepared.plan.full_text();\n        input.cwd = claude_cli::pipeline::effective_cwd(prepared.project_work_dir.as_deref().map(std::path::Path::new));\n        notice = prepared.image_notice;\n        snapshot = Some((prepared.art_dir, prepared.art_before));\n    }\n    if crate::runtime::procs::CHILDREN.take_cancel(req) {\n        emit(app, event(req, conv.as_deref(), \"done\", None));\n        return Ok(());\n    }\n    let stream = backend.start_with_tools(input, tool_options).map_err(|e| e.to_string())?;\n    let mut finalizer = None;\n    let timeout = Duration::from_millis(config.agentd.request_timeout_ms);\n    loop {\n        let ev = match stream.recv_timeout(timeout) {\n            Ok(event) => event,\n            // Only the supervisor sees all agentd events (including hidden reasoning/usage).\n            // Let it own turn deadlines and deliver the specific error followed by done.\n            Err(error) if matches!(error.downcast_ref(), Some(stream::StreamError::Timeout)) => continue,\n            Err(error) => { let _ = backend.cancel(req); return Err(error.to_string()); }\n        };\n        if host_tools::handle_sandbox(backend.as_ref(), &ev).map_err(|e| e.to_string())? { continue; }\n        if ev.kind == \"done\" {\n            if let (Some(finalizer), Some((artifacts, before))) = (finalizer.take(), snapshot.take()) {\n                let finalizer: claude_cli::pipeline::TurnStream = finalizer;\n                finalizer.finish(&artifacts, &before);\n            } else { emit(app, ev); }\n            if conv.is_none() { let _ = backend.close(req); }\n            crate::runtime::procs::CHILDREN.take_cancel(req);\n            break;\n        }\n        if ev.kind == \"meta\" && !legacy {\n            emit(app, ev);\n            finalizer = Some(claude_cli::pipeline::TurnStream::new(app.clone(), req.into(), conv.clone(), notice.take()));\n            continue;\n        }\n        if let Some(finalizer) = &mut finalizer { finalizer.record_backend_event(&ev); }\n        emit(app, ev);\n    }\n    Ok(())\n}\npub(crate) fn emit(app: &AppHandle, event: ChatStreamEvent) { let _ = app.emit(\"chat:stream\", event); }\n  const id = currentProviderId.value;\n  if (id === \"auto\") return \"Auto\";\n  return providersStore.providers.find((x) => x.id === id)?.name || \"Auto\";\n});\nfunction pickProvider(id: string) {\n  const cid = app.currentConvId;\n  if (cid) {\n    convProvider.value = { ...convProvider.value, [cid]: id };\n  } else {\n    pendingProvider.value = id;\n  }\n  showProviderPanel.value = false;\n}\n\n/** 当前工具条各开关拼出的发送选项(父层「重新生成」/「今日建议」与主发送共用同一份形状) */\nfunction sendOptions(convId?: string | null): ChatSendOptions {\n  return {\n    permissionMode: permMode.value,\n    skillIds: Array.from(skillsStore.enabledSkills),\n    useKb: kbMode.value || undefined,\n    agentMode: agentMode.value,\n    workMode: workMode.value,\n    providerId: providerForConv(convId),\n  };\n}\n\n// ─────────── 工作流包「使用」→ 填入输入框 ───────────\n// 右侧「工作流包」点「使用」时，store 发来拼装好的提示词：已有内容则追加，否则填入；\n// 随后聚焦并把光标移到末尾。带 nonce 以便重复使用同一包也能触发。\nfunction applyInsert(req: { text: string; n: number } | null | undefined) {\n  if (!req || !req.text) return;\n  const cur = input.value.trimEnd();\n  input.value = cur ? `${cur}\\n\\n${req.text}` : req.text;\n  workflowsStore.clearInsert();\n  nextTick(() => {\n    const el = inputEl.value;\n    !orchestrateMode.value &&\n    (batchMode.value || detectLongTask(prompt));\n  if (wantBatch) {\n    await longTaskStore.runBatchBuild(convId, prompt, display, {\n      permissionMode: permMode.value,\n      skillIds: Array.from(skillsStore.enabledSkills),\n      useKb: kbMode.value || undefined,\n      providerId: sendProviderId,\n    });\n    return;\n  }\n\n  // 交给 chat store：推 user 气泡 + 调后端 + 记录 reqId/sending（按对话 id，多开）\n  await chatStore.send(convId, prompt, display, attached, {\n    permissionMode: permMode.value,\n    skillIds: Array.from(skillsStore.enabledSkills),\n    // 目标模式下，本条输入框内容即完成条件\n    goal: goalMode.value && text ? text : undefined,\n    dynamicWorkflow: orchestrateMode.value || undefined,\n    useKb: kbMode.value || undefined,\n    agentMode: agentMode.value,\n    workMode: workMode.value,\n    providerId: sendProviderId,\n  });\n}\n\nasync function cancel() {\n  // 先停掉分批编排循环（否则它会在本轮 done 后又发下一批），再取消在飞的子进程\n  if (app.currentConvId) longTaskStore.stop(app.currentConvId);\n  await chatStore.cancel(app.currentConvId);\n}\n\n// ── 清空上下文（右下角橡皮擦）：消息清零避免上下文过长;旧内容后台自动沉淀入记忆库 ──\nconst clearingCtx = ref(false);\nasync function clearContext() {\n  const cid = app.currentConvId;\n  if (!cid || clearingCtx.value) return;\n  if (\n    !confirm(\n      \"清空本对话的全部历史上下文？\\n\\n有价值的内容（反馈、偏好、决策）会自动沉淀进记忆库，生成的文件不受影响。\"\n    )\n      if (!providerId) {\r\n        const bind = JSON.parse(localStorage.getItem(\"polaris.convProvider.v1\") || \"{}\") || {};\r\n        providerId = bind[convId] || \"auto\";\r\n      }\r\n    } catch {\r\n      /* localStorage 不可用就让后端按默认档预热 */\r\n    }\r\n    chatApi.prewarm({\r\n      conversationId: convId,\r\n      permissionMode: opts?.permissionMode,\r\n      workMode,\r\n      providerId,\r\n      dynamicWorkflow: opts?.dynamicWorkflow,\r\n    });\r\n  }\r\n\r\n  /** 发送一条消息：推入 user 气泡 + 调后端，记录 reqId/sending（不阻塞，多开） */\r\n  async function send(\r\n    convId: string,\r\n    prompt: string,\r\n    displayText: string,\r\n    files: AttachedFile[] | undefined,\r\n    opts: {\r\n      permissionMode: PermissionMode;\r\n      skillIds: string[];\r\n      goal?: string;\r\n      dynamicWorkflow?: boolean;\r\n      useKb?: boolean;\r\n      batchBuild?: boolean;\r\n      batchSize?: number;\r\n      agentMode?: string;\r\n      workMode?: string;\r\n      providerId?: string;\r\n    }\r\n  ) {\r\n    // 关键: 先确保流式监听已挂上, 否则本轮的 delta 可能早于监听器注册而丢失\r\n    // —— 现象正是「第一次发消息看不到输出, 但后台仍在运行」。尤其是从「更多」各工坊\r\n    // (Deck/Web/视频/自媒体/自动化)直接发起时, ChatPanel 尚未挂载、init 从未被调用。\r\n    await init();\r\n    const sessions = useSessionsStore();\r\n    const arr = ensureArr(convId);\r\n    arr.push({\r\n      role: \"user\",\r\n      text: displayText,\r\n      files: files && files.length ? files : undefined,\r\n      at: Date.now(),\r\n    });\r\n    sendingByConv.value[convId] = true;\r\n    // 清掉上一轮可能残留的 reqId(若用户在 chat_send resolve 前就取消, send 可能晚于\r\n    // cancel 删除条目后落地, 留下永不清理的孤儿 reqId)。新一轮开始前先抹掉, 关掉这个活锁竞态。\r\n    delete reqByConv.value[convId];\r\n    touchActivity(convId);\r\n    sessions.start(convId, displayText.slice(0, 18));\r\n    try {\r\n      const reqId = await chatApi.send({\r\n        imagePaths: uploadedImagePaths(files),\r\n        prompt,\r\n        permissionMode: opts.permissionMode,\r\n        skillIds: opts.skillIds,\r\n        goal: opts.goal,\r\n        dynamicWorkflow: opts.dynamicWorkflow,\r\n        useKb: opts.useKb,\r\n        batchBuild: opts.batchBuild,\r\n        batchSize: opts.batchSize,\r\n        agentMode: opts.agentMode,\r\n        workMode: opts.workMode,\r\n        providerId: opts.providerId,\r\n        conversationId: convId,\r\n      });\r\n      reqByConv.value[convId] = reqId;\r\n    } catch (e: any) {\r\n      arr.push({\r\n        role: \"assistant\",\r\n        text: `[发送失败] ${humanizeError(e)}`,\r\n        at: Date.now(),\r\n        err: true,\r\nsrc/components/chat/shared.ts:419:export interface ChatSendOptions {\nsrc/components/chat/ChatComposer.vue:68:  type ChatSendOptions,\nsrc/components/chat/ChatComposer.vue:625:function sendOptions(convId?: string | null): ChatSendOptions {\nsrc/components/chat/BriefingCenter.vue:19:import { useIdleRunner, type ChatSendOptions, type Suggestion } from \"./shared\";\nsrc/components/chat/BriefingCenter.vue:23:  sendOptions: (convId: string) => ChatSendOptions;\n<script setup lang=\"ts\">\nimport { ref, onMounted, onActivated } from \"vue\";\nimport {\n  sandbox,\n  cube,\n  type SandboxStatus,\n  type CubeConfig,\n  type CubeStatus,\n} from \"../api\";\nimport Workstations from \"../../coworker/components/Workstations.vue\";\n\n// KeepAlive 的 include 按组件 name 匹配 → 显式命名，确保本视图被缓存\ndefineOptions({ name: \"SandboxStatus\" });\n// 挂载/状态就绪时通知 App 收起加载条\nconst emit = defineEmits<{ ready: [] }>();\n\nconst status = ref<SandboxStatus | null>(null);\nconst log = ref<string[]>([]);\nconst busy = ref(false);\nconst execCmd = ref(\"claude --version\");\nconst execOut = ref(\"\");\n\n// CubeSandbox (E2B) 后端配置\nconst cubeCfg = ref<CubeConfig>({ backend: \"docker\", endpoint: \"\", apiKey: \"\" });\nconst cubeStat = ref<CubeStatus | null>(null);\nconst cubeBusy = ref(false);\n\nasync function refresh() {\n  try {\n    status.value = await sandbox.status();\n  } catch (e: any) {\n    log.value.unshift(`[refresh] ${e?.message ?? e}`);\n  }\n}\nasync function loadCube() {\n  try {\n    cubeCfg.value = await cube.configGet();\n    cubeStat.value = await cube.status();\n  } catch (e: any) {\n    log.value.unshift(`[cube] ${e?.message ?? e}`);\n  }\n}\nasync function saveCube() {\n  cubeBusy.value = true;\n  try {\n    cubeCfg.value = await cube.configSet(cubeCfg.value);\n    cubeStat.value = await cube.status();\n    log.value.unshift(`[cube] 已保存 · backend=${cubeCfg.value.backend}`);\n  } catch (e: any) {\n    log.value.unshift(`[cube error] ${e?.message ?? e}`);\n  } finally {\n    cubeBusy.value = false;\n  }\n}\nasync function testCube() {\n  cubeBusy.value = true;\n  try {\n    cubeStat.value = await cube.status();\n  } finally {\n    cubeBusy.value = false;\n  }\n}\nonMounted(() => {\n  // 不 await：状态异步填入即可，不被 docker 慢查询拖住\n  refresh();\n  loadCube();\n  // 等数字人 / 状态卡片画出来后再通知 App 收起加载条（遮住挂载那一下的卡顿）\n  setTimeout(() => emit(\"ready\"), 420);\n});\n\n// KeepAlive：缓存后切回不重新挂载（瞬开）；顺手异步刷新状态保持新鲜，不阻塞\nonActivated(() => {\n  refresh();\n});\n\nasync function build() {\n  busy.value = true;\n  log.value.unshift(\"[build] 开始构建镜像 polaris-sandbox:alpine …\");\n  try {\n    const out = await sandbox.build();\n    log.value.unshift(out);\n  } catch (e: any) {\n    log.value.unshift(`[build error] ${e?.message ?? e}`);\n  } finally {\n    busy.value = false;\n    await refresh();\n  }\n}\nasync function start() {\n  busy.value = true;\n  try {\n    log.value.unshift(await sandbox.start());\n  } catch (e: any) {\n    log.value.unshift(`[start error] ${e?.message ?? e}`);\n  } finally {\n    busy.value = false;\n    await refresh();\n  }\n}\nasync function stop() {\n  busy.value = true;\n  try {\n    log.value.unshift(await sandbox.stop());\n  } catch (e: any) {\n    log.value.unshift(`[stop error] ${e?.message ?? e}`);\n  } finally {\n    busy.value = false;\n    await refresh();\n  }\n}\nasync function runCmd() {\n  if (!execCmd.value.trim()) return;\n  busy.value = true;\n  execOut.value = \"(running …)\";\n  try {\n    execOut.value = await sandbox.exec(execCmd.value);\n  } catch (e: any) {\n    execOut.value = `[error] ${e?.message ?? e}`;\n  } finally {\n    busy.value = false;\n  }\n}\n</script>\n\n<template>\n  <div class=\"sandbox\">\n    <div class=\"head\">\n      <div class=\"title\">安全沙箱层</div>\n      <div class=\"sub\">\n        基于 <code>alpine:3.20</code> 的极简镜像 · 原生二进制\n        <code>claude-code</code> (apk 装, 无 Node) · 镜像 ~120MB\n      </div>\n    </div>\n\n    <!-- 协作工位：9 个古风数字人，有任务执笔工作，无任务摸鱼 -->\n    <Workstations />\n\n    <!-- CubeSandbox (E2B) 后端：替换 Docker 方案的可选后端 -->\n    <div class=\"cube\">\n      <div class=\"cube-head\">\n        <span class=\"cube-title\">沙箱后端 · CubeSandbox (E2B)</span>\n        <span\n          class=\"cube-badge\"\n          :class=\"{\n            on: cubeStat?.reachable,\n            warn: cubeStat?.configured && !cubeStat?.reachable,\n          }\"\n        >\n          {{\n            !cubeStat?.configured\n              ? \"未配置\"\n              : cubeStat?.reachable\n              ? \"已连通\"\n              : \"不可达\"\n          }}\n        </span>\n      </div>\n      <div class=\"cube-desc\">\n        CubeSandbox 是腾讯云基于 RustVMM+KVM 的微虚机沙箱，兼容 E2B。它需运行在\n        <strong>Linux/KVM</strong>（远程主机 / WSL2 / 云），把端点 URL 填到这里即可把执行从\n        Docker 切到 CubeSandbox。\n      </div>\n      <div class=\"cube-row\">\n        <label>后端</label>\n        <select v-model=\"cubeCfg.backend\">\n          <option value=\"docker\">Docker（本机，默认）</option>\n          <option value=\"e2b\">CubeSandbox / E2B（端点）</option>\n        </select>\n      </div>\n      <div class=\"cube-row\">\n        <label>端点 URL</label>\n        <input\n          v-model=\"cubeCfg.endpoint\"\n          placeholder=\"https://your-cubesandbox-host:port\"\n        />\n      </div>\n      <div class=\"cube-row\">\n        <label>API Key</label>\n        <input v-model=\"cubeCfg.apiKey\" placeholder=\"可空（E2B_API_KEY）\" />\n      </div>\n//! Map Polaris keys to daemon UUIDs; never pass a conversation ID as a new UUID.\nuse super::{client::Client, protocol::{Command, Open, Session, Configure, SessionOptions}};\nuse super::super::TurnRequest;\nuse serde::{Serialize, Deserialize};\nuse serde_json::Value;\nuse sha2::{Digest, Sha256};\nuse std::path::PathBuf;\n#[derive(Clone, Serialize, Deserialize)]\npub struct SessionInfo { pub id: String, pub cwd: PathBuf, pub model: Value, pub tools: Vec<String> }\nfn path(client: &Client, key: &str) -> PathBuf {\n    client.config.session_map.join(format!(\"{:x}.json\", Sha256::digest(key.as_bytes())))\n}\npub fn open(client: &Client, input: &TurnRequest, tools: super::super::ToolOptions) -> anyhow::Result<SessionInfo> {\n    let mut options = super::input::options(client, input)?;\n    options.sandbox = Some(tools.sandbox);\n    options.expert_prompt = Some(tools.expert_prompt.unwrap_or_default());\n    let file = path(client, &input.session_id);\n    let previous: Option<SessionInfo> = match std::fs::read(&file) {\n        Ok(bytes) => Some(serde_json::from_slice(&bytes)?),\n        Err(e) if e.kind() == std::io::ErrorKind::NotFound => None,\n        Err(e) => return Err(e.into()),\n    };\n    let cwd = std::fs::canonicalize(&input.cwd)?;\n    let id = previous.as_ref().map(|s| s.id.clone());\n    if let Some(previous) = &previous {\n        if previous.cwd != cwd { let _ = client.call(Command::Close(Session { session_id: previous.id.clone() })); }\n    }\n    let response = client.call(Command::Open(Open { session_id: id, cwd: Some(cwd.to_string_lossy().into()), options: options.clone() }));\n    let response = match response {\n        Ok(v) => v,\n        Err(e) if e.to_string().starts_with(\"SESSION_ALREADY_OPEN:\") => {\n            let previous = previous.as_ref().ok_or_else(|| anyhow::anyhow!(\"AgentdSessionMappingMissing\"))?;\n            client.call(Command::Configure(Configure { session_id: previous.id.clone(), options: options.clone() }))?\n        }\n        Err(e) if e.to_string().starts_with(\"SESSION_NOT_FOUND:\") => {\n            client.call(Command::Open(Open { session_id: None, cwd: Some(cwd.to_string_lossy().into()), options: options.clone() }))?\n        }\n        Err(e) => return Err(e),\n    };\n    anyhow::ensure!(response.get(\"reopenRequired\") != Some(&Value::Bool(true)), \"AgentdSessionReopenRequired\");\n    let info = SessionInfo {\n        id: response.get(\"sessionId\").and_then(Value::as_str).ok_or_else(|| anyhow::anyhow!(\"AgentdMissingSessionId\"))?.into(),\n        cwd, model: response.get(\"model\").cloned().ok_or_else(|| anyhow::anyhow!(\"AgentdMissingModel\"))?,\n        tools: serde_json::from_value(response.get(\"tools\").cloned().ok_or_else(|| anyhow::anyhow!(\"AgentdMissingTools\"))?)?,\n    };\n    std::fs::create_dir_all(&client.config.session_map)?;\n    let temporary = file.with_extension(\"tmp\");\n    std::fs::write(&temporary, serde_json::to_vec(&info)?)?;\n    std::fs::rename(temporary, file)?;\n    Ok(info)\n}\npub fn close(client: &Client, key: &str) -> anyhow::Result<()> {\n    let file = path(client, key);\n    if !file.exists() { return Ok(()); }\n    let info: SessionInfo = serde_json::from_slice(&std::fs::read(&file)?)?;\n    match client.call(Command::Close(Session { session_id: info.id })) {\n        Err(e) if !e.to_string().starts_with(\"SESSION_NOT_FOUND:\") => Err(e),\n        _ => Ok(()),\n    }\n}\n\n/// The SDK is authoritative for busy detection; an active turn rejects configuration.\npub fn configure(client: &Client, key: &str, options: SessionOptions) -> anyhow::Result<Value> {\n    let info: SessionInfo = serde_json::from_slice(&std::fs::read(path(client, key))?)?;\n    client.call(Command::Configure(Configure { session_id: info.id, options }))\n}\n","exit_code":0,"status":"completed"}}
