 去掉 nodejs/npm 整层死重。\n# 体积下限被 claude 二进制本身卡住 (内嵌运行时, 单文件 ~100MB),\n# 整镜像估计 ~110-140MB (相比 node 版的 ~250-400MB 明显瘦身)。\n#\n# 安全策略 (容器运行时由 docker run 注入):\n#   --memory=4g --cpus=2\n#   --security-opt=no-new-privileges\n#   -v ~/Polaris:/workspace        (读写)\n#   -v ~/Polaris/PolarisKB:/kb:ro  (只读)\n\nFROM alpine:3.20\n\n# 原生二进制在 musl(Alpine) 上的运行依赖: libgcc / libstdc++ / 系统 ripgrep\n# (Claude Code 内置 ripgrep 不兼容 musl, 需系统版 + USE_BUILTIN_RIPGREP=0)\nRUN apk add --no-cache ca-certificates ripgrep libgcc libstdc++ \\\n    && update-ca-certificates\n\n# 添加官方 Claude Code apk 仓库 (stable 频道) 并安装原生包。\n# --no-cache 会刷新含新仓库的索引, 无需单独 apk update。\nRUN wget -O /etc/apk/keys/claude-code.rsa.pub \\\n        https://downloads.claude.ai/keys/claude-code.rsa.pub \\\n    && echo \"https://downloads.claude.ai/claude-code/apk/stable\" >> /etc/apk/repositories \\\n    && apk add --no-cache claude-code\n\nENV USE_BUILTIN_RIPGREP=0\n\n# 非 root 用户 (busybox adduser 会自动建同名组)\nRUN adduser -D -u 1000 polaris\n\nWORKDIR /workspace\nUSER polaris\n\n# 默认指令由 docker run 覆盖 (sleep infinity)\nCMD [\"sh\"]\n","exit_code":0,"status":"completed"}}
