#[test]
fn drop_replies_to_every_deferred_and_pending_request_immediately() -> anyhow::Result<()> {
    for panic in [false, true] {
        let now = Instant::now();
        let status = Arc::new(Mutex::new(BackendStatus::new("pi")));
        let mut state = State {
            experts: Default::default(),
            config: super::super::tests::config(), status: status.clone(),
            active: Arc::new(Mutex::new(HashMap::new())), routes: HashMap::new(),
            pending: HashMap::new(), deferred: Vec::new(), counter: 0, failures: 0,
            next_start: now, last_ping: now, started: now, last_used: now, stopping: false,
        };
        let mut receivers = Vec::new();
        // Keep sender clones alive: channel disconnection cannot pass this test.
        let mut senders = Vec::new();
        for index in 0..3 {
            let (reply, rx) = std::sync::mpsc::sync_channel(1);
            senders.push(reply.clone());
            receivers.push(rx);
            state.deferred.push((Command::Ping(Empty {}), reply, now));
            let (reply, rx) = std::sync::mpsc::sync_channel(1);
            senders.push(reply.clone());
            receivers.push(rx);
            state.pending.insert(Id::Text(format!("pending-{index}")),
                Pending { reply: Some(reply), since: now, ping: false });
        }
        state.pending.insert(Id::Text("health-ping".into()),
            Pending { reply: None, since: now, ping: true });
        let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(move || {
            let _state = state;
            assert!(!panic, "injected supervisor unwind");
        }));
        assert_eq!(outcome.is_err(), panic);
        for rx in receivers {
            assert_eq!(rx.try_recv()?, Err(super::super::routes::SUPERVISOR_EXITED.into()));
        }
        assert_eq!(status.lock().last_error.as_deref(), Some(super::super::routes::SUPERVISOR_EXITED));
        drop(senders);
    }
    Ok(())
}
//! Supervisor-owned restore transaction: apply, verify, then release queued calls.
//! Configuration failures leave daemon health intact and retry on a later ping.
use super::{State, Process, Command, Empty, Id};
use super::super::{experts::{self, ExpertConfig}, protocol};
use serde_json::Value;

#[derive(Default)]
pub(super) struct Restore {
    waiting: Option<Id>,
    next: Option<Command>,
    expected: Option<ExpertConfig>,
    verifying: bool,
}
impl Restore {
    pub(super) fn busy(&self) -> bool { self.waiting.is_some() || self.next.is_some() }
}

impl State {
    pub(super) fn restore_experts(&mut self, actual: Option<ExpertConfig>) {
        if self.experts.busy() || self.status.lock().experts_synced == Some(true) { return; }
        let result = (|| -> anyhow::Result<()> {
            let Some(saved) = experts::load(&self.config.expert_settings)? else {
                self.expert_sync_finished(Ok(()));
                return Ok(());
            };
            let actual = actual.ok_or_else(|| anyhow::anyhow!("ExpertConfigReadUnsupported"))?
                .normalized(experts::prompt_limit()?)?;
            if actual == saved {
                self.expert_sync_finished(Ok(()));
            } else {
                self.experts.next = Some(Command::Apply(protocol::Apply {
                    config: Some(serde_json::json!({ "experts": saved })), credentials: None,
                }));
                self.experts.expected = Some(saved);
            }
            Ok(())
        })();
        if let Err(error) = result { self.expert_sync_finished(Err(error)); }
    }

    pub(super) fn send_expert_request(&mut self, process: &Process) -> anyhow::Result<()> {
        if let Some(command) = self.experts.next.take() {
            self.request(process, command, None)?;
            self.experts.waiting = Some(Id::Text(format!("rust-{}", self.counter)));
        }
        Ok(())
    }

    pub(super) fn expert_response(&mut self, id: &Id, result: &Result<Value, String>) -> bool {
        if self.experts.waiting.as_ref() != Some(id) { return false; }
        self.experts.waiting = None;
        let result = (|| -> anyhow::Result<()> {
            let value = result.as_ref().map_err(|error| anyhow::anyhow!("{error}"))?;
            if self.experts.verifying {
                let actual = protocol::check_ping(value.clone())?.experts
                    .ok_or_else(|| anyhow::anyhow!("ExpertConfigReadUnsupported"))?
                    .normalized(experts::prompt_limit()?)?;
                anyhow::ensure!(Some(&actual) == self.experts.expected.as_ref(), "ExpertConfigApplyMismatch");
                self.expert_sync_finished(Ok(()));
            } else {
                self.experts.verifying = true;
                self.experts.next = Some(Command::Ping(Empty {}));
            }
            Ok(())
        })();
        if let Err(error) = result { self.expert_sync_finished(Err(error)); }
        true
    }

    fn expert_sync_finished(&mut self, result: anyhow::Result<()>) {
        self.experts = Default::default();
        let mut status = self.status.lock();
        status.experts_synced = Some(result.is_ok());
        status.expert_sync_error = result.err().map(|error| error.to_string());
    }
}
use super::{protocol::Command, supervisor, translate::Translator};
use super::super::{config::Agentd, stream::Mailbox, BackendStatus};
use std::{sync::{Arc, mpsc}, time::{Duration, Instant}};
use parking_lot::Mutex;
use serde_json::Value;
pub type Reply = mpsc::SyncSender<Result<Value, String>>;
pub enum Control {
    Request(Command, Reply),
    Register { session: String, req: String, translator: Translator, stream: Arc<Mailbox>, timeout: Duration, reservation: (Arc<Mutex<std::collections::HashSet<String>>>, String), reply: Reply },
    Cancel(String, Reply),
    Bind(String, String, Reply),
    Fail(String, String),
    Stop,
    #[cfg(test)]
    TestExit(bool),
    #[cfg(test)]
    TestClose,
}
pub struct Client {
    pub config: Agentd,
    tx: tokio::sync::mpsc::Sender<Control>,
    pub status: Arc<Mutex<BackendStatus>>,
    pub active: Arc<Mutex<std::collections::HashMap<String, String>>>,
}
impl Client {
    pub fn new(config: Agentd) -> anyhow::Result<Arc<Self>> {
        let runtime = tokio::runtime::Builder::new_current_thread().enable_all().build()?;
        let (tx, rx) = tokio::sync::mpsc::channel(config.channel_capacity);
        let client = Arc::new(Self { config: config.clone(), tx,
            status: Arc::new(Mutex::new(BackendStatus::new("pi"))), active: Arc::new(Mutex::new(Default::default())) });
        let status = client.status.clone();
        let active = client.active.clone();
        std::thread::Builder::new().name("agentd-supervisor".into()).spawn(move || {
            runtime.block_on(supervisor::run(config, rx, status, active));
        })?;
        Ok(client)
    }
    pub fn send(&self, mut command: Control) -> anyhow::Result<()> {
        let deadline = Instant::now() + Duration::from_millis(self.config.request_timeout_ms);
        loop {
            match self.tx.try_send(command) {
                Ok(()) => return Ok(()),
                Err(tokio::sync::mpsc::error::TrySendError::Full(c)) => command = c,
                Err(_) => anyhow::bail!("AgentdSupervisorStopped"),
            }
            anyhow::ensure!(Instant::now() < deadline, "AgentdControlTimeout");
            std::thread::sleep(Duration::from_millis(self.config.control_poll_ms));
        }
    }
    pub fn call(&self, command: Command) -> anyhow::Result<Value> {
        let (tx, rx) = mpsc::sync_channel(1);
        self.send(Control::Request(command, tx))?;
        self.wait(rx)
    }
    pub fn wait(&self, rx: mpsc::Receiver<Result<Value, String>>) -> anyhow::Result<Value> {
        // Budget queue/serialization separately from the actor's request deadline,
        // so its specific write/response error wins over the caller's fallback.
        let timeout = self.config.request_timeout_ms.saturating_mul(2)
            .saturating_add(self.config.supervisor_tick_ms.saturating_mul(2));
        rx.recv_timeout(Duration::from_millis(timeout)).map_err(|error| {
            anyhow::anyhow!(match error {
                mpsc::RecvTimeoutError::Disconnected => super::routes::SUPERVISOR_EXITED,
                mpsc::RecvTimeoutError::Timeout => "AgentdRequestTimeout",
            })
        })?.map_err(anyhow::Error::msg)
    }
    pub fn cancel(&self, req: &str) -> anyhow::Result<()> {
        let (tx, rx) = mpsc::sync_channel(1);
        self.send(Control::Cancel(req.into(), tx))?;
        self.wait(rx).map(|_| ())
    }
    pub fn stop(&self) { let _ = self.send(Control::Stop); }
}
impl Drop for Client { fn drop(&mut self) { let _ = self.tx.try_send(Control::Stop); } }

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn reply_disconnect_and_timeout_have_distinct_errors() -> anyhow::Result<()> {
        let mut config = super::super::tests::config();
        config.request_timeout_ms = 1;
        config.supervisor_tick_ms = 1;
        let (tx, _control) = tokio::sync::mpsc::channel(1);
        let client = Client { config, tx,
            status: Arc::new(Mutex::new(BackendStatus::new("pi"))),
            active: Arc::new(Mutex::new(Default::default())) };
        // A stale actor failure must not mask why recv_timeout returned.
        client.status.lock().last_error = Some("AgentdRestarting".into());
        let (reply, rx) = mpsc::sync_channel(1);
        drop(reply);
        let error = client.wait(rx).err().ok_or_else(|| anyhow::anyhow!("expected exit"))?;
        assert_eq!(error.to_string(), super::super::routes::SUPERVISOR_EXITED);
        let (_reply, rx) = mpsc::sync_channel(1);
        let error = client.wait(rx).err().ok_or_else(|| anyhow::anyhow!("expected timeout"))?;
        assert_eq!(error.to_string(), "AgentdRequestTimeout");
        let (reply, rx) = mpsc::sync_channel(1);
        reply.send(Err("AgentdWriterBackpressure".into()))?;
        let error = client.wait(rx).err().ok_or_else(|| anyhow::anyhow!("expected actor error"))?;
        assert_eq!(error.to_string(), "AgentdWriterBackpressure");
        Ok(())
    }
}

