        depth: parentEntry ? parentEntry.depth + 1 : 0, children: new Set(),
        toolProfile: options.toolProfile ?? config.defaultToolProfile, lastUsed: Date.now(), queueReservations: 0 };
      this.entries.set(id, entry);
